/* Lot 111: relative colours with missing origin components, alone and mixed (generated by scripts/lot111_gen.py; expectations from scripts/lot111_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static char g_o[64];

/* 1, the 24-bit colour and the alpha (0..255) the reader paints, or 0 */
static const char *col(const char *v) {
    unsigned int rgb = 0;
    int a = 0;
    if (!wf_cssprop_color(v, (int)strlen(v), &rgb, &a)) return "0";
    snprintf(g_o, sizeof(g_o), "1 %06x %d", rgb, a);
    return g_o;
}

static void test_l111_rel_0(void) {
    TEST_ASSERT_EQUAL_STRING("1 0000bc 128", col("color-mix(in xyz, oklch(from hwb(from rgb(10 20 30 / none) none calc(b) b) 0 c h), rgb(0 0 255 / 0.5))"));
    TEST_ASSERT_EQUAL_STRING("1 aaaaaa 159", col("color-mix(in srgb-linear, white, hsl(from rgb(none 0 0 / 50%) h calc(s - 1) calc(l) / alpha) 75%)"));
    TEST_ASSERT_EQUAL_STRING("1 7d8cd4 255", col("color-mix(in lab, lab(from lab(60 none -40) a calc(a) calc(b - 45)), hsl(none 20% 60%))"));
    TEST_ASSERT_EQUAL_STRING("1 576d68 255", col("color-mix(in lab, oklch(0.6 0.1 200), hwb(from oklch(0.6 0.1 none) h none 60) 30%)"));
    TEST_ASSERT_EQUAL_STRING("1 ffffff 255", col("color-mix(in hsl, white, lab(from oklab(from oklch(none 0.15 30) l a 0.1) l a b) 75%)"));
    TEST_ASSERT_EQUAL_STRING("0", col("rgb(from color(xyz 0.2 none 0.3) calc(g + 10%) 128 calc(b))"));
    TEST_ASSERT_EQUAL_STRING("0", col("hsl(from hsl(none 50% 50%) calc(h) calc(s + 10%) calc(l))"));
    TEST_ASSERT_EQUAL_STRING("1 b23f98 223", col("color-mix(in hwb, lch(from hwb(none 10% 20%) l calc(c / 2) calc(h)) 75%, rgb(0 0 255 / 0.5))"));
    TEST_ASSERT_EQUAL_STRING("1 c44f00 255", col("oklab(from hsl(from lch(50 30 none) h s l / alpha) calc(l) calc(a * 2) 50%)"));
    TEST_ASSERT_EQUAL_STRING("1 89956d 255", col("color-mix(in lch, lab(from hsl(200 80% none) l b b / alpha), lab(60 -20 40))"));
    TEST_ASSERT_EQUAL_STRING("1 373737 255", col("lch(from hsl(none 50% 50%) calc(l / 2) h h / alpha)"));
    TEST_ASSERT_EQUAL_STRING("1 a64200 255", col("color-mix(in srgb, rgb(200 0 0), rgb(from lab(from lab(60 none -40) 50% -30 100 / none) g g -20))"));
    TEST_ASSERT_EQUAL_STRING("1 000000 255", col("lch(from oklch(none 0.15 30) calc(l * 2) calc(c / 2) h)"));
    TEST_ASSERT_EQUAL_STRING("1 1e1e00 128", col("hwb(from rgb(10 20 30 / none) 60 0 b / 0.5)"));
    TEST_ASSERT_EQUAL_STRING("1 983434 255", col("color-mix(in srgb, hwb(from lab(60 none -40) h calc(w) 60 / alpha), rgb(200 0 0))"));
    TEST_ASSERT_EQUAL_STRING("1 b0667e 255", col("lch(from oklch(0.6 0.1 none) l c calc(h))"));
    TEST_ASSERT_EQUAL_STRING("1 ff86b0 255", col("lch(from color(from color(display-p3 none 0.5 0.5) srgb-linear calc(r) calc(alpha - 0.5) calc(alpha)) l c none)"));
    TEST_ASSERT_EQUAL_STRING("1 276635 128", col("lab(from color(srgb 0.2 0.4 none) l calc(a) calc(b / 2) / 0.5)"));
    TEST_ASSERT_EQUAL_STRING("1 bd4f89 159", col("color-mix(in srgb, lch(80 none 40), lab(from oklab(from lab(40 30 none) l calc(alpha - 0.2) b) calc(l) a b / 0.5) 75%)"));
    TEST_ASSERT_EQUAL_STRING("1 ac0000 255", col("color-mix(in srgb-linear, oklab(from lab(none 20 30) calc(l * 0.5 + 0.05) calc(a / 2) b) 30%, rgb(200 0 0))"));
}

